const item = $input.first();
const secret = $env.SHOP_OWNER_WEBHOOK_SECRET;
const headers = item.json.headers || {};
const body = (item.json.body && typeof item.json.body === 'object') ? item.json.body : item.json;

const headerSecret = String(
  headers['x-shop-webhook-secret'] ||
  headers['X-Shop-Webhook-Secret'] ||
  ''
);
const bodySecret = String(body.webhookSecret || item.json.webhookSecret || '');
const authorized = !!secret && (headerSecret === secret || bodySecret === secret);
const hasCatalogApiKey = String($env.CATALOG_API_KEY || '').trim().length > 0;

const name = String(body.name || '').trim();
const description = String(body.description || name).trim();
const categoryId = Number(body.categoryId);
const brandId = Number(body.brandId);
const price = Number(body.price ?? body.basePrice);
const inventory = Number(body.inventory);
const seoTitleFa = String(body.seoTitleFa || name).trim();
const metaDescriptionFa = String(body.metaDescriptionFa || description).slice(0, 160);
const slug = String(body.slug || '').trim();
const imageUrl = String(body.imageUrl || '').trim();
const width = Number(body.width);
const height = Number(body.height);
const depth = Number(body.depth);
const weight = Number(body.weight);
const hasMagnification = body.magnification !== undefined && body.magnification !== null && String(body.magnification).trim() !== '';
const hasWorkingDistance = body.workingDistance !== undefined && body.workingDistance !== null && String(body.workingDistance).trim() !== '';
const hasFieldOfView = body.fieldOfView !== undefined && body.fieldOfView !== null && String(body.fieldOfView).trim() !== '';
const magnification = hasMagnification ? Number(body.magnification) : null;
const workingDistance = hasWorkingDistance ? Number(body.workingDistance) : null;
const fieldOfView = hasFieldOfView ? Number(body.fieldOfView) : null;

const binary = item.binary || {};
const imageKey = Object.keys(binary).find((k) => binary[k]);
const outBinary = {};
if (imageKey) {
  outBinary.image = binary[imageKey];
}

let error = '';
let httpStatus = 200;
if (!authorized) {
  error = 'Unauthorized webhook';
  httpStatus = 401;
} else if (!hasCatalogApiKey) {
  error = 'CATALOG_API_KEY is not set';
  httpStatus = 502;
} else if (!name || !Number.isFinite(categoryId) || categoryId <= 0 || !Number.isFinite(brandId) || brandId <= 0) {
  error = 'name, categoryId and brandId are required';
  httpStatus = 400;
} else if (!Number.isFinite(price) || price <= 0 || !Number.isInteger(inventory) || inventory < 0) {
  error = 'price must be > 0 and inventory must be a whole number >= 0';
  httpStatus = 400;
} else if (hasMagnification && (!Number.isFinite(magnification) || magnification <= 0)) {
  error = 'magnification must be > 0 when provided';
  httpStatus = 400;
} else if (hasWorkingDistance && (!Number.isFinite(workingDistance) || workingDistance <= 0)) {
  error = 'workingDistance must be > 0 when provided';
  httpStatus = 400;
} else if (hasFieldOfView && (!Number.isFinite(fieldOfView) || fieldOfView <= 0)) {
  error = 'fieldOfView must be > 0 when provided';
  httpStatus = 400;
}

return [{
  json: {
    ok: !error,
    error,
    httpStatus,
    hasImage: !!imageKey,
    name,
    description,
    categoryId,
    brandId,
    price,
    inventory,
    seoTitleFa,
    metaDescriptionFa,
    slug: slug || undefined,
    imageUrl: imageUrl || undefined,
    width: Number.isFinite(width) ? width : 0,
    height: Number.isFinite(height) ? height : 0,
    depth: Number.isFinite(depth) ? depth : 0,
    weight: Number.isFinite(weight) ? weight : 0,
    magnification: hasMagnification ? magnification : undefined,
    workingDistance: hasWorkingDistance ? workingDistance : undefined,
    fieldOfView: hasFieldOfView ? fieldOfView : undefined,
    apiBase: $env.API_BASE_URL || 'http://backend:8080/api',
    siteBase: $env.CONTENT_ADMIN_BASE_URL || 'https://lucaloupe.com'
  },
  binary: outBinary
}];

const created = $input.first().json;
const ctx = $('Parse Payload').item.json;
const n8nErr = created.error && typeof created.error === 'object'
  ? (created.error.message || JSON.stringify(created.error))
  : '';

if (created.isSuccess === false) {
  return [{ json: { ok: false, httpStatus: created.error === 'Unauthorized' ? 401 : 400, error: created.error || 'Create catalog item failed' } }];
}

const data = created.data || {};
const productId = data.productId || data.ProductId;
const offerId = data.offerId || data.OfferId;
const imageId = data.imageId || data.ImageId || null;
if (!productId || !offerId) {
  return [{ json: { ok: false, httpStatus: 502, error: n8nErr || created.error || 'CatalogItems response missing ids' } }];
}

const url = `${String(ctx.siteBase).replace(/\/$/, '')}/fa/products/${productId}`;
return [{ json: {
  ok: true,
  httpStatus: 200,
  productId,
  offerId,
  imageId,
  name: ctx.name,
  price: ctx.price,
  inventory: ctx.inventory,
  magnification: ctx.magnification,
  workingDistance: ctx.workingDistance,
  fieldOfView: ctx.fieldOfView,
  url
} }];
